// The adventure scene: the session's meters as an adventurer's gear on the
// stone floor of a keep: a mana potion for the context, an hourglass for the
// prompt cache, a chest of gold for the five-hour limit, and a quiver of
// arrows for the week. Each has its number underneath in the 3x5 pixel font.
//
// The hourglass runs by itself over the cache's life, so the band need not be
// redrawn to keep it current. At a quarter of the context or less a spare
// vial waits beside the potion; while the conversation is compacted the
// potion fills up again, sparkling.

import { wordsOf } from '../language'
import type { MeterScene, Meters } from './index'
import { countdown, COUNTDOWN_CSS, HEIGHT, hourSteps, level, percentText, pixelText, px, refill, REFILL_CSS, runsLow, SCALE, sceneSvg, SLOT, smallSceneSvg, stageOf, WIDTH } from './pixels'

// Objects stand on the stone floor at y 9.
const FLOOR_Y = 9

const STONE = '#6E6A63'
const STONE_DARK = '#57534D'
const GLASS = '#A8C8D8'
const CORK = '#A0785A'
const MANA = '#4F74D9'
const MANA_LIGHT = '#8FB0FF'
const SPARK = '#F5E6A8'
const WOOD = '#8B5A2B'
const WOOD_DARK = '#6B4220'
const SAND = '#E0C080'
const IRON = '#5A5A5A'
const GOLD = '#F2C14E'
const GOLD_DARK = '#C8962E'
const LEATHER = '#9A6438'
const LEATHER_DARK = '#74482A'
const SHAFT = '#C8A878'
const FEATHER = '#C0443A'
const FEATHER_LIGHT = '#E8E6DC'

// The potion's inside, row by row from the bottom: [y, first x, last x].
const POTION: [number, number, number][] = [[7, 6, 9], [6, 5, 10], [5, 5, 10], [4, 5, 10], [3, 6, 9]]

const potionRows = (x: number, rows: number) =>
  POTION.slice(0, rows).map(([y, a, b]) => px(x + a, y, b - a + 1, 1)).join('')

// Context: a mana potion, as full as the context left, bubbling. At a quarter
// or less a spare vial stands by; while the conversation is compacted the
// potion fills up again with sparkles over it.
const potion = (left: number | null, x: number, isCompacting: boolean) => {
  const rows = level(left, POTION.length)
  const isLow = runsLow(left)
  const mana = isCompacting
    ? `<g style="${refill(POTION.length - rows)}">${potionRows(x, POTION.length)}</g>`
    : potionRows(x, rows)
  const top = POTION[Math.max(0, (isCompacting ? POTION.length : rows) - 1)]?.[0] ?? 8
  return `
    <g fill="${MANA}">${mana}</g>
    ${rows > 1 || isCompacting ? `<g fill="${MANA_LIGHT}"><g class="bubble1">${px(x + 6, 6)}</g><g class="bubble2">${px(x + 8, 7)}</g></g>` : ''}
    <g fill="${GLASS}">
      ${px(x + 6, 0, 1, 3)}${px(x + 9, 0, 1, 3)}${px(x + 5, 3)}${px(x + 10, 3)}
      ${px(x + 4, 4, 1, 3)}${px(x + 11, 4, 1, 3)}${px(x + 5, 7)}${px(x + 10, 7)}${px(x + 6, 8, 4, 1)}
    </g>
    <g fill="#FFFFFF" opacity="0.5">${px(x + 6, 4, 1, 2)}</g>
    <g fill="${CORK}">${px(x + 7, -1, 2, 2)}</g>
    ${isLow && !isCompacting ? `<g fill="${GLASS}">${px(x + 12, 5, 1, 4)}${px(x + 14, 5, 1, 4)}${px(x + 13, 8)}</g><g fill="${MANA}">${px(x + 13, 6, 1, 2)}</g><g fill="${CORK}">${px(x + 13, 4)}</g>` : ''}
    ${isCompacting ? `<g fill="${SPARK}"><g class="spark1">${px(x + 5, Math.min(top, 3) - 2)}</g><g class="spark2">${px(x + 10, Math.min(top, 3) - 3)}</g><g class="spark3">${px(x + 12, 1)}</g></g>` : ''}
    ${percentText(left, x)}`
}

// The sand in the hourglass's bulbs: the top one's four rows, the last in the
// neck, and the bottom one's three. The glass is centred on x 7.
const topSand = (x: number) => `${px(x + 5, 0, 5, 2)}${px(x + 6, 2, 3, 1)}${px(x + 7, 3)}`
const bottomSand = (x: number) => `${px(x + 6, 5, 3, 1)}${px(x + 5, 6, 5, 2)}`

// Cache: an hourglass whose sand runs by itself over the cache's life, the top
// bulb draining and the bottom one filling, one grain at a time falling
// through the neck; it has run out once the cache expires.
const hourglass = (left: number | null, ttl: number, x: number) => {
  const isOut = left !== null && left <= 0
  const timing = left === null || isOut ? '' : `animation-duration: ${ttl}s; animation-delay: -${ttl - left}s`
  const sand = left === null
    ? `<g fill="${SAND}">${topSand(x)}</g>`
    : isOut
      ? `<g fill="${SAND}">${bottomSand(x)}</g>`
      : `<g fill="${SAND}"><g class="drain" style="${timing}">${topSand(x)}</g><g class="pile" style="${timing}">${bottomSand(x)}</g><g class="fall">${px(x + 7, 4)}</g></g>`
  return `
    <g fill="${GLASS}" opacity="0.6">
      ${px(x + 4, 0, 1, 2)}${px(x + 10, 0, 1, 2)}${px(x + 5, 2)}${px(x + 9, 2)}
      ${px(x + 6, 3, 1, 2)}${px(x + 8, 3, 1, 2)}
      ${px(x + 5, 5)}${px(x + 9, 5)}${px(x + 4, 6, 1, 2)}${px(x + 10, 6, 1, 2)}
    </g>
    ${sand}
    <g fill="${WOOD}">${px(x + 2, -1, 11, 1)}${px(x + 2, 8, 11, 1)}</g>
    <g fill="${WOOD_DARK}">${px(x + 2, 0, 1, 8)}${px(x + 12, 0, 1, 8)}</g>
    ${left === null ? pixelText('--', x) : isOut ? pixelText('0m', x) : countdown(left, x)}`
}

// The gold heaped in the chest, row by row from the rim up: [y, first x, last x].
const HEAP: [number, number, number][] = [[4, 4, 11], [3, 5, 10], [2, 6, 9], [1, 7, 8]]

// The last few coins, before the chest is empty.
const FEW_COINS: [number, number, number] = [4, 6, 8]

// Five-hour limit: an open chest whose heap of gold is the window still free,
// down to a few coins, a glint on it now and then.
const chest = (used: number | null, x: number) => {
  const left = used === null ? null : 100 - used
  const steps = left === null ? HEAP.length + 1 : level(left, HEAP.length + 1)
  const heap = steps === 0 ? [] : steps === 1 ? [FEW_COINS] : HEAP.slice(0, steps - 1)
  const top = heap[heap.length - 1]
  return `
    <g fill="${WOOD_DARK}">${px(x + 3, 1, 10, 4)}${px(x + 4, 0, 8, 1)}</g>
    <g fill="${IRON}">${px(x + 3, 2, 10, 1)}</g>
    <g fill="${GOLD}">${heap.map(([y, a, b]) => px(x + a, y, b - a + 1, 1)).join('')}</g>
    <g fill="${GOLD_DARK}">${heap.map(([y, , b]) => px(x + b, y)).join('')}${heap.length > 1 ? px(x + 6, 4) + px(x + 9, 3) : ''}</g>
    ${top ? `<g class="glint" fill="#FFFFFF">${px(x + top[1] + 1, top[0])}</g>` : ''}
    <g fill="${WOOD}">${px(x + 3, 5, 10, 4)}</g>
    <g fill="${IRON}">${px(x + 3, 5, 10, 1)}${px(x + 5, 6, 1, 3)}${px(x + 10, 6, 1, 3)}</g>
    <g fill="${GOLD}">${px(x + 7, 6, 2, 2)}</g>
    <g fill="${WOOD_DARK}">${px(x + 7, 7)}</g>
    ${percentText(left, x)}`
}

// Where each arrow stands in the quiver, as [x, the top of its fletching],
// the first ones drawn last to go.
const ARROWS: [number, number][] = [[7, -2], [9, -1], [5, -1], [8, 0], [6, 0], [10, 0]]

// Weekly limit: a quiver with an arrow for every sixth of the week still free.
const quiver = (used: number | null, x: number) => {
  const left = used === null ? null : 100 - used
  const count = left === null ? ARROWS.length : Math.max(left > 0 ? 1 : 0, Math.round((left / 100) * ARROWS.length))
  const arrows = ARROWS.slice(0, count)
  return `
    <g fill="${SHAFT}">${arrows.map(([ax, ty]) => px(x + ax, ty + 2, 1, 3 - ty)).join('')}</g>
    ${arrows.map(([ax, ty], i) => `<g fill="${i % 2 === 0 ? FEATHER : FEATHER_LIGHT}">${px(x + ax, ty, 1, 2)}</g>`).join('')}
    <g fill="${LEATHER}">${px(x + 5, 3, 6, 5)}${px(x + 6, 8, 4, 1)}</g>
    <g fill="${LEATHER_DARK}">${px(x + 5, 3, 6, 1)}${px(x + 5, 6, 6, 1)}${px(x + 10, 4, 1, 4)}</g>
    <g fill="${LEATHER_DARK}">${px(x + 11, 2)}${px(x + 12, 1)}${px(x + 4, 7)}${px(x + 3, 8)}</g>
    ${percentText(left, x)}`
}

// Stone slabs, each four pixels wide, a darker seam between them.
const floor = () =>
  Array.from({ length: WIDTH / 4 }, (_, i) => `<g fill="${i % 2 === 0 ? STONE : STONE_DARK}">${px(i * 4, FLOOR_Y, 4, 1)}</g>`).join('')

const adventureSvg = (f: Meters) =>
  sceneSvg(
    `${COUNTDOWN_CSS}
    ${REFILL_CSS}
    .bubble1 { animation: bubble 1.8s steps(3) infinite; }
    .bubble2 { animation: bubble 1.8s steps(3) -0.9s infinite; }
    @keyframes bubble { 0% { transform: translate(0, 0); opacity: 0; } 30% { opacity: 1; } 100% { transform: translate(0, -3px); opacity: 0; } }
    .spark1 { animation: twinkle 0.6s steps(1) infinite; }
    .spark2 { animation: twinkle 0.6s steps(1) -0.2s infinite; }
    .spark3 { animation: twinkle 0.6s steps(1) -0.4s infinite; }
    @keyframes twinkle { 0%, 49.9% { opacity: 1; } 50%, 100% { opacity: 0; } }
    .drain { animation-name: drain; animation-timing-function: steps(4); animation-fill-mode: forwards; }
    .pile { animation-name: pile; animation-timing-function: steps(3); animation-fill-mode: forwards; }
    @keyframes drain { from { clip-path: inset(0 0 0 0); } to { clip-path: inset(4px 0 0 0); } }
    @keyframes pile { from { clip-path: inset(3px 0 0 0); } to { clip-path: inset(0 0 0 0); } }
    .fall { animation: fall 1.8s steps(3) infinite; }
    @keyframes fall { 0% { transform: translate(0, 0); opacity: 1; } 100% { transform: translate(0, 3px); opacity: 0.5; } }
    .glint { animation: glint 2.6s steps(1) infinite; }
    @keyframes glint { 0%, 79.9% { opacity: 0; } 80%, 89.9% { opacity: 1; } 90%, 100% { opacity: 0; } }`,
    `
  ${floor()}
  ${potion(f.contextLeft, 0, f.isCompacting)}
  ${hourglass(f.cacheLeft, f.cacheTtl, SLOT)}
  ${chest(f.fiveHour, SLOT * 2)}
  ${quiver(f.week, SLOT * 3)}`,
  )

// The scene in the small size, on the stone floor: the mana potion, as full
// as the context left, a spare vial beside it at a quarter or less, filling up
// while compacting; the hourglass, its sand running over the cache's life, a
// grain falling through the neck now and then while it runs; the chest, its heap of gold going with the five-hour limit; and the quiver,
// losing its arrows over the week.
const CENTERS = [4, 14, 25.5, 35]

// The potion's inside, row by row from the bottom: [y, first x, last x].
const SMALL_FLASK: readonly (readonly [number, number, number])[] = [[6, 3, 5], [5, 2, 6], [4, 2, 6], [3, 2, 6], [2, 3, 5]]

const adventureSmall = (f: Meters) => {
  const mana = f.isCompacting ? 5 : ([0, 1, 3, 5][stageOf(f.contextLeft)] ?? 0)
  const isLow = !f.isCompacting && runsLow(f.contextLeft)
  const inside = (rows: readonly (readonly [number, number, number])[]) => rows.map(([y, a, b]) => px(a, y, b - a + 1, 1)).join('')
  const potion = `
    <g fill="${CORK}">${px(4, 0)}</g>
    <g fill="${GLASS}">${px(4, 1)}${inside(SMALL_FLASK)}</g>
    ${mana > 0 ? `<g${f.isCompacting ? ' class="fill"' : ''} fill="${MANA}">${inside(SMALL_FLASK.slice(0, mana))}</g>` : ''}
    ${mana > 1 ? `<g fill="${MANA_LIGHT}">${px(3, 7 - mana)}</g><g class="bubble" fill="${SPARK}">${px(4, 5)}</g>` : ''}
    ${isLow ? `<g fill="${CORK}">${px(8, 4)}</g><g fill="${GLASS}">${px(8, 5)}</g><g fill="${MANA}">${px(8, 6)}</g>` : ''}`

  const glass = `<g fill="${GLASS}">${px(13, 1, 3, 2)}${px(14, 3)}${px(13, 4, 3, 2)}</g>`
  const frame = `<g fill="${WOOD_DARK}">${px(12, 0, 5, 1)}${px(12, 6, 5, 1)}</g><g fill="${WOOD}">${px(12, 1, 1, 5)}${px(16, 1, 1, 5)}</g>`
  const isRunning = f.cacheLeft !== null && f.cacheLeft > 0
  const hourglass = `${hourSteps(
    f,
    [
      `${glass}<g fill="${SAND}">${px(13, 1, 3, 2)}${px(14, 5)}</g>${frame}`,
      `${glass}<g fill="${SAND}">${px(13, 2, 3, 1)}${px(13, 5, 3, 1)}</g>${frame}`,
      `${glass}<g fill="${SAND}">${px(14, 2)}${px(13, 5, 3, 1)}${px(14, 4)}</g>${frame}`,
    ],
    `${glass}<g fill="${SAND}">${px(13, 4, 3, 2)}</g>${frame}`,
  )}${isRunning ? `<g class="grain" fill="${SAND}">${px(14, 3)}</g>` : ''}`

  const fiveLeft = f.fiveHour === null ? null : 100 - f.fiveHour
  const step = stageOf(fiveLeft)
  const gold = [
    '',
    px(25, 2, 2, 1),
    px(23, 2, 6, 1),
    `${px(24, 1, 4, 1)}${px(23, 2, 6, 1)}`,
  ][step]
  const chest = `
    <g fill="${WOOD_DARK}">${px(23, 0, 6, 1)}${px(22, 3, 8, 1)}</g>
    ${gold ? `<g fill="${GOLD}">${gold}</g><g fill="${GOLD_DARK}">${step > 1 ? px(24, 2) + px(27, 2) : px(26, 2)}</g>` : ''}
    <g fill="${WOOD}">${px(22, 4, 8, 3)}</g>
    <g fill="${IRON}">${px(22, 4, 1, 3)}${px(29, 4, 1, 3)}</g>
    <g fill="${GOLD}">${px(25, 5, 2, 1)}</g>`

  const weekLeft = f.week === null ? null : 100 - f.week
  const arrows = [0, 1, 2, 3][stageOf(weekLeft)] ?? 0
  const quiver = `
    ${[35, 34, 36].slice(0, arrows).map(x => `<g fill="${SHAFT}">${px(x, 1, 1, 2)}</g><g fill="${x === 35 ? FEATHER_LIGHT : FEATHER}">${px(x, 0)}</g>`).join('')}
    <g fill="${LEATHER}">${px(34, 3, 3, 4)}</g>
    <g fill="${LEATHER_DARK}">${px(36, 3, 1, 4)}${px(34, 4, 2, 1)}</g>`

  const floor = `<g fill="${STONE}">${px(0, 7, 40, 1)}</g><g fill="${STONE_DARK}">${Array.from({ length: 13 }, (_, i) => px(i * 3 + 2, 7)).join('')}</g>`

  return smallSceneSvg(
    `
    .fill { animation: fill 2s steps(5) both; }
    @keyframes fill { from { clip-path: inset(5px 0 0 0); } to { clip-path: inset(0 0 0 0); } }
    .bubble { animation: bubble 1.2s steps(1) infinite; }
    @keyframes bubble { 0%, 32.9% { transform: translate(0, 0); } 33%, 65.9% { transform: translate(0, -1px); } 66%, 100% { opacity: 0; } }
    .grain { animation: grain 3s steps(1) infinite; }
    @keyframes grain { 0%, 33.2% { transform: translate(0, 0); } 33.3%, 66.5% { transform: translate(0, 1px); } 66.6%, 100% { opacity: 0; } }`,
    `${floor}${potion}${hourglass}${chest}${quiver}`,
  )
}

export const adventureScene: MeterScene = {
  name: 'adventure',
  label: wordsOf(t => t.scenes.adventure),
  width: WIDTH,
  height: HEIGHT,
  scale: SCALE,
  svg: adventureSvg,
  small: { svg: adventureSmall, centers: CENTERS },
}

files.hooks/scenes/balcony.ts:
// The balcony scene: the session's meters as things on a sunny balcony: a
// watering can for the context, a daisy in a pot for the prompt cache, a bird
// feeder for the five-hour limit, and a jar of honey for the week. Each has its
// number underneath in the 3x5 pixel font.
//
// The daisy wilts by itself over the cache's life, so the band need not be
// redrawn to keep it current. At a quarter of the context or less a rain cloud
// gathers over the watering can; while the conversation is compacted it rains
// and the can fills up.

import { wordsOf } from '../language'
import type { MeterScene, Meters } from './index'
import { countdown, COUNTDOWN_CSS, HEIGHT, hops, hourSteps, level, percentText, pixelText, px, refill, REFILL_CSS, runsLow, SCALE, sceneSvg, SLOT, smallSceneSvg, stageOf, WIDTH } from './pixels'

// Objects stand on the floor tiles at y 9.
const FLOOR_Y = 9

const TILE = '#B5674A'
const TILE_DARK = '#8F4E37'
const RAIL = '#3A332D'
const CAN = '#5E8C6A'
const CAN_DARK = '#476B51'
const WATER = '#8FD3F0'
const CLOUD = '#B8C4D6'
const CLOUD_DARK = '#8E9AB0'
const POT = '#C2693E'
const POT_DARK = '#9A4F2E'
const SOIL = '#5A3A24'
const STEM = '#6FA35A'
const STEM_DRY = '#8A7A4A'
const PETAL = '#F4F1E6'
const PETAL_DRY = '#A07850'
const HEART = '#F5C26B'
const WOOD = '#A0785A'
const WOOD_DARK = '#7A5A42'
const GLASS = '#8C8A84'
const SEED = '#D9B26A'
const SEED_DARK = '#A07840'
const BIRD = '#5B8FD6'
const BIRD_DARK = '#3F6DAE'
const BIRD_BELLY = '#A9C6EE'
const BEAK = '#F5A623'
const EYE = '#F4F1E6'
const STRIPE = '#7A5520'
const HONEY = '#E0A030'
const HONEY_LIGHT = '#F2C45A'
const CLOTH = '#B5483E'
const CREAM = '#E8E6DC'
const BEE = '#F5C26B'

// The can holds this many rows of water.
const CAN_ROWS = 5

// A small rain cloud over the can's mouth. While the conversation is
// compacted, rain falls from it into the can.
const cloud = (x: number, isRaining: boolean) => `
  <g class="drift">
    <g fill="${CLOUD}">${px(x + 6, -2, 4, 1)}${px(x + 5, -1, 7, 1)}</g>
    <g fill="${CLOUD_DARK}">${px(x + 5, -1)}${px(x + 11, -1)}</g>
  </g>
  ${isRaining ? `<g fill="${WATER}">
    <g class="rain1">${px(x + 6, 0)}</g><g class="rain2">${px(x + 8, 0)}</g><g class="rain3">${px(x + 10, 0)}</g>
  </g>` : ''}`

// Context: a watering can, open at the top and seen through, its handle at
// the back and its spout rising to the left; its water level is the context
// left. A drop falls from its rose now and then while there is water to spare. At a
// quarter or less a rain cloud gathers over it; while the conversation is
// compacted the cloud rains and the can fills up.
const wateringCan = (left: number | null, x: number, isCompacting: boolean) => {
  const rows = level(left, CAN_ROWS)
  const isLow = runsLow(left)
  const water = isCompacting
    ? `<g style="${refill(CAN_ROWS - rows)}">${px(x + 6, 8 - CAN_ROWS, 5, CAN_ROWS)}</g>`
    : rows > 0 ? px(x + 6, 8 - rows, 5, rows) : ''
  return `
    <g fill="${WATER}">${water}</g>
    <g fill="${CAN}">${px(x + 5, 3, 1, 6)}${px(x + 11, 3, 1, 6)}${px(x + 6, 8, 5, 1)}${px(x + 4, 6)}${px(x + 3, 5)}${px(x + 2, 4)}</g>
    <g fill="${CAN_DARK}">${px(x + 4, 2, 2, 1)}${px(x + 11, 2, 2, 1)}${px(x + 13, 3)}${px(x + 14, 4, 1, 2)}${px(x + 13, 6)}${px(x + 12, 6)}${px(x + 1, 3)}${px(x, 2, 1, 2)}</g>
    ${rows > 1 && !isCompacting ? `<g fill="${WATER}"><g class="drip">${px(x, 4)}</g></g>` : ''}
    ${isLow || isCompacting ? cloud(x, isCompacting) : ''}
    ${percentText(left, x)}`
}

// A daisy's head around (cx, cy): petals five pixels across around a
// one-pixel heart.
const bloom = (cx: number, cy: number, petal: string, heart: string, petalOpacity = 1) => `
  <g fill="${petal}" opacity="${petalOpacity}">${px(cx, cy - 2)}${px(cx - 1, cy - 1, 3, 1)}${px(cx - 2, cy, 2, 1)}${px(cx + 1, cy, 2, 1)}${px(cx - 1, cy + 1, 3, 1)}${px(cx, cy + 2)}</g>
  <g fill="${heart}">${px(cx, cy)}</g>`

// The daisy in its four stages over the cache's life: upright, nodding,
// drooping, wilted; each a group shown for its quarter.
const daisy = (x: number, timing: string) => `
  <g class="stage0" style="${timing}">
    <g fill="${STEM}">${px(x + 8, 3, 1, 2)}${px(x + 9, 3)}${px(x + 7, 4)}</g>
    ${bloom(x + 8, 0, PETAL, HEART)}
  </g>
  <g class="stage1" style="${timing}">
    <g fill="${STEM}">${px(x + 8, 3, 1, 2)}${px(x + 9, 3)}${px(x + 7, 4)}</g>
    ${bloom(x + 10, 0, PETAL, HEART)}
  </g>
  <g class="stage2" style="${timing}">
    <g fill="${STEM}">${px(x + 8, 1, 1, 4)}${px(x + 9, 0)}${px(x + 10, 0)}${px(x + 7, 4)}</g>
    ${bloom(x + 12, 2, PETAL, HEART, 0.8)}
  </g>
  <g class="stage3" style="${timing}">
    <g fill="${STEM_DRY}">${px(x + 8, 2, 1, 3)}${px(x + 9, 1)}${px(x + 10, 1)}${px(x + 11, 2)}${px(x + 7, 4)}</g>
    <g fill="${PETAL_DRY}">${px(x + 12, 3)}${px(x + 11, 4)}${px(x + 13, 4)}${px(x + 12, 5, 2, 1)}</g>
    <g fill="${HEART}" opacity="0.7">${px(x + 12, 4)}</g>
  </g>`

// The pot the daisy grows in.
const pot = (x: number) => `
  <g fill="${POT}">${px(x + 5, 5, 7, 1)}${px(x + 6, 6, 5, 3)}</g>
  <g fill="${POT_DARK}">${px(x + 5, 5, 7, 1)}${px(x + 10, 6, 1, 3)}</g>
  <g fill="${SOIL}">${px(x + 6, 5, 5, 1)}</g>`

// Cache: a daisy in a pot. It wilts by itself over the cache's life, one stage
// a quarter, and stays wilted, with a fallen petal, once the cache expires.
const flowerPot = (left: number | null, ttl: number, x: number) => {
  if (left === null) {
    return `${pot(x)}<g fill="${STEM}">${px(x + 8, 3, 1, 2)}${px(x + 9, 3)}</g>${pixelText('--', x)}`
  }
  if (left <= 0) {
    return `${pot(x)}
      <g fill="${STEM_DRY}">${px(x + 8, 3, 1, 2)}${px(x + 9, 2)}${px(x + 10, 2)}${px(x + 11, 3)}${px(x + 7, 4)}</g>
      <g fill="${PETAL_DRY}">${px(x + 11, 4)}${px(x + 12, 5)}${px(x + 13, 8)}</g>
      ${pixelText('0m', x)}`
  }
  return `
    ${daisy(x, `animation-duration: ${ttl}s; animation-delay: -${ttl - left}s`)}
    ${pot(x)}
    ${countdown(left, x)}`
}

// Where the seeds sit in the feeder's glass, from the bottom.
const SEED_ROWS = 5

// Five-hour limit: a bird feeder whose glass holds the seeds left, a row for
// every fifth of the window, a bluebird pecking at the tray. With the seeds
// gone, so is the bird.
const feeder = (used: number | null, x: number) => {
  const left = used === null ? null : 100 - used
  const rows = left === null ? SEED_ROWS : level(left, SEED_ROWS)
  return `
    <g fill="${WOOD_DARK}">${px(x + 9, 6, 1, 2)}${px(x + 8, 8, 3, 1)}${px(x + 8, -2, 3, 1)}</g>
    <g fill="${WOOD}">${px(x + 6, -1, 7, 1)}${px(x + 1, 5, 14, 1)}${px(x + 14, 4)}</g>
    <g fill="${GLASS}">${px(x + 7, 0, 1, 5)}${px(x + 11, 0, 1, 5)}</g>
    ${rows > 0 ? `<g fill="${SEED}">${px(x + 8, 5 - rows, 3, rows)}</g>
    <g fill="${SEED_DARK}">${Array.from({ length: rows }, (_, i) => px(x + 8 + ((i * 2) % 3), 4 - i)).join('')}${px(x + 6, 4)}${px(x + 12, 4)}</g>
    <g fill="${BIRD}">${px(x + 2, 3, 3, 2)}</g>
    <g fill="${BIRD_DARK}">${px(x + 2, 3, 2, 1)}${px(x + 1, 3)}${px(x, 2)}</g>
    <g fill="${BIRD_BELLY}">${px(x + 3, 4, 2, 1)}</g>
    <g class="peck">
      <g fill="${BIRD}">${px(x + 4, 2, 2, 1)}${px(x + 5, 3)}</g>
      <g fill="${EYE}">${px(x + 5, 2)}</g>
      <g fill="${BEAK}">${px(x + 6, 3)}</g>
    </g>` : ''}
    ${percentText(left, x)}`
}

// Where the honey sits in the jar, from the bottom.
const HONEY_ROWS = 5

// Weekly limit: a jar of honey under a checked cloth that empties as the
// week's limit is used, a row for every fifth of the week, a bee buzzing
// around it while there is honey.
const honeyJar = (used: number | null, x: number) => {
  const left = used === null ? null : 100 - used
  const rows = left === null ? HONEY_ROWS : level(left, HONEY_ROWS)
  return `
    ${rows > 0 ? `<g fill="${HONEY}">${px(x + 6, 8 - rows, 5, rows)}</g><g fill="${HONEY_LIGHT}">${px(x + 7, 8 - rows, 1, rows)}</g>` : ''}
    <g fill="${GLASS}">${px(x + 5, 3, 1, 6)}${px(x + 11, 3, 1, 6)}${px(x + 6, 8, 5, 1)}</g>
    <g fill="${CREAM}">${px(x + 4, 1, 9, 1)}${px(x + 4, 2)}${px(x + 12, 2)}</g>
    <g fill="${CLOTH}">${px(x + 5, 1)}${px(x + 7, 1)}${px(x + 9, 1)}${px(x + 11, 1)}${px(x + 5, 2, 7, 1)}</g>
    <g fill="#FFFFFF" opacity="0.4">${px(x + 10, 4, 1, 2)}</g>
    ${rows > 0 ? `<g class="bee">
      <g fill="${BEE}">${px(x + 13, -1)}${px(x + 15, -1)}</g><g fill="${STRIPE}">${px(x + 14, -1)}</g>
      <g class="wings" fill="${CREAM}" opacity="0.8">${px(x + 14, -2)}</g>
    </g>` : ''}
    ${percentText(left, x)}`
}

// The balcony: a dim railing behind everything and a row of floor tiles. The
// balusters stand where no glass or open can lets them show through.
const railing = () => `
  <g fill="${RAIL}">${px(0, 0, WIDTH, 1)}${Array.from({ length: WIDTH / 8 }, (_, i) => px(i * 8 + 3, 1, 1, FLOOR_Y - 1)).join('')}</g>`

const floor = () =>
  Array.from({ length: WIDTH / 4 }, (_, i) => `<g fill="${i % 2 === 0 ? TILE : TILE_DARK}">${px(i * 4, FLOOR_Y, 4, 1)}</g>`).join('')

const balconySvg = (f: Meters) =>
  sceneSvg(
    `${COUNTDOWN_CSS}
    ${REFILL_CSS}
    .drift { animation: drift 4s steps(1) infinite; }
    @keyframes drift { 0%, 49.9% { transform: translate(0, 0); } 50%, 100% { transform: translate(1px, 0); } }
    .rain1 { animation: rain 0.6s steps(3) infinite; }
    .rain2 { animation: rain 0.6s steps(3) -0.2s infinite; }
    .rain3 { animation: rain 0.6s steps(3) -0.4s infinite; }
    @keyframes rain { from { transform: translate(0, 0); } to { transform: translate(0, 3px); } }
    .drip { animation: drip 3s steps(1) infinite; }
    @keyframes drip { 0%, 69.9% { opacity: 0; transform: translate(0, 0); } 70%, 79.9% { opacity: 1; transform: translate(0, 1px); } 80%, 89.9% { opacity: 1; transform: translate(0, 3px); } 90%, 100% { opacity: 0; transform: translate(0, 4px); } }
    .stage0 { animation-name: stage0; }
    .stage1 { animation-name: stage1; }
    .stage2 { animation-name: stage2; }
    .stage3 { animation-name: stage3; }
    .stage0, .stage1, .stage2, .stage3 { animation-timing-function: steps(1); animation-fill-mode: forwards; }
    @keyframes stage0 { 0%, 24.9% { opacity: 1; } 25%, 100% { opacity: 0; } }
    @keyframes stage1 { 0%, 24.9% { opacity: 0; } 25%, 49.9% { opacity: 1; } 50%, 100% { opacity: 0; } }
    @keyframes stage2 { 0%, 49.9% { opacity: 0; } 50%, 74.9% { opacity: 1; } 75%, 100% { opacity: 0; } }
    @keyframes stage3 { 0%, 74.9% { opacity: 0; } 75%, 100% { opacity: 1; } }
    .peck { animation: peck 1.4s steps(1) infinite; }
    @keyframes peck { 0%, 59.9% { transform: translate(0, 0); } 60%, 69.9% { transform: translate(0, 1px); } 70%, 79.9% { transform: translate(0, 0); } 80%, 89.9% { transform: translate(0, 1px); } 90%, 100% { transform: translate(0, 0); } }
    .bee { animation: buzz 3.2s steps(16) infinite; }
    @keyframes buzz { 0% { transform: translate(0, 0); } 25% { transform: translate(-3px, 1px); } 50% { transform: translate(-6px, 0); } 75% { transform: translate(-3px, -1px); } 100% { transform: translate(0, 0); } }
    .wings { animation: flap 0.2s steps(1) infinite; }
    @keyframes flap { 0%, 49.9% { opacity: 0.8; } 50%, 100% { opacity: 0; } }`,
    `
  ${railing()}
  ${floor()}
  ${wateringCan(f.contextLeft, 0, f.isCompacting)}
  ${flowerPot(f.cacheLeft, f.cacheTtl, SLOT)}
  ${feeder(f.fiveHour, SLOT * 2)}
  ${honeyJar(f.week, SLOT * 3)}`,
  )

// The scene in the small size, on the tiles: the watering can, as full as
// the context left, a rain cloud over it at a quarter or less that rains into
// it while compacting; the daisy, upright, nodding, wilting and fallen over
// the cache's life; the feeder, its seeds going with the five-hour limit, the
// bluebird pecking at it; and the jar of honey, emptying over the week, the
// bee buzzing around it.
const CENTERS = [5, 13, 23, 33]

// Where the bee flies, from where it is drawn: around the jar's right side,
// then over its lid and back.
const BEE_PATH: [number, number][] = [[0, 0], [1, 1], [1, 3], [0, 4], [1, 2], [-2, 0], [-4, 0], [-2, 0]]

const balconySmall = (f: Meters) => {
  const water = f.isCompacting ? 3 : ([0, 1, 2, 3][stageOf(f.contextLeft)] ?? 0)
  const isLow = f.isCompacting || runsLow(f.contextLeft)
  const can = `
    <g fill="${CAN_DARK}">${px(4, 3, 3, 3)}${px(8, 3, 1, 2)}</g>
    ${water > 0 ? `<g${f.isCompacting ? ' class="fill"' : ''} fill="${WATER}">${px(4, 6 - water, 3, water)}</g>` : ''}
    <g fill="${CAN}">${px(3, 3, 1, 4)}${px(7, 3, 1, 4)}${px(4, 6, 3, 1)}${px(2, 4)}${px(1, 3)}</g>
    ${isLow ? `<g fill="${CLOUD}">${px(5, 0, 3, 1)}${px(4, 1, 5, 1)}</g><g fill="${CLOUD_DARK}">${px(5, 1, 3, 1)}</g>` : ''}
    ${f.isCompacting ? `<g fill="${WATER}"><g class="drop0">${px(4, 2)}</g><g class="drop1">${px(6, 2)}</g></g>` : ''}`

  const pot = `<g fill="${POT}">${px(11, 5, 5, 1)}</g><g fill="${POT_DARK}">${px(12, 6, 3, 1)}</g>`
  const head = (x: number, y: number, petal: string) =>
    `<g fill="${petal}">${px(x - 1, y)}${px(x + 1, y)}${px(x, y - 1)}${px(x, y + 1)}</g><g fill="${HEART}">${px(x, y)}</g>`
  const daisy = hourSteps(
    f,
    [
      `${pot}<g fill="${STEM}">${px(13, 3, 1, 2)}</g>${head(13, 1, PETAL)}`,
      `${pot}<g fill="${STEM}">${px(13, 4)}${px(14, 3)}</g>${head(15, 2, PETAL)}`,
      `${pot}<g fill="${STEM_DRY}">${px(13, 4)}${px(14, 3)}</g>${head(15, 4, PETAL_DRY)}`,
    ],
    `${pot}<g fill="${STEM_DRY}">${px(13, 3, 1, 2)}</g><g fill="${PETAL_DRY}">${px(16, 6)}${px(17, 6)}</g>`,
  )

  const fiveLeft = f.fiveHour === null ? null : 100 - f.fiveHour
  const seeds = [0, 1, 2, 3][stageOf(fiveLeft)] ?? 0
  const feeder = `
    <g fill="${GLASS}">${px(24, 2, 3, 3)}</g>
    ${seeds > 0 ? `<g fill="${SEED}">${px(24, 5 - seeds, 3, seeds)}</g><g fill="${SEED_DARK}">${px(25, 4)}</g>` : ''}
    <g fill="${WOOD_DARK}">${px(23, 1, 5, 1)}${px(25, 6)}</g>
    <g fill="${WOOD}">${px(23, 5, 6, 1)}</g>
    <g fill="${BIRD_DARK}">${px(18, 4)}</g>
    <g fill="${BIRD}">${px(19, 4, 2, 1)}</g>
    <g fill="${BIRD_BELLY}">${px(19, 5, 2, 1)}</g>
    <g class="peck"><g fill="${BIRD}">${px(21, 3)}</g><g fill="${BEAK}">${px(22, 3)}</g></g>`

  const weekLeft = f.week === null ? null : 100 - f.week
  const honey = [0, 1, 2, 4][stageOf(weekLeft)] ?? 0
  const jar = `
    ${honey > 0 ? `<g fill="${HONEY}">${px(32, 6 - honey, 3, honey)}</g><g fill="${HONEY_LIGHT}">${px(32, 6 - honey, 3, 1)}</g>` : ''}
    <g fill="${GLASS}">${px(31, 2, 1, 5)}${px(35, 2, 1, 5)}${px(32, 6, 3, 1)}</g>
    <g fill="${CLOTH}">${px(31, 1, 5, 1)}</g><g fill="${CREAM}">${px(32, 1)}${px(34, 1)}</g>
    <g class="bee"><g fill="${BEE}">${px(37, 0)}</g><g fill="${STRIPE}">${px(38, 0)}</g></g>`

  const tiles = `<g fill="${TILE}">${px(0, 7, 40, 1)}</g><g fill="${TILE_DARK}">${[3, 7, 11, 15, 19, 23, 27, 31, 35, 39].map(x => px(x, 7)).join('')}</g>`

  return smallSceneSvg(
    `
    .fill { animation: fill 2s steps(3) both; }
    @keyframes fill { from { clip-path: inset(3px 0 0 0); } to { clip-path: inset(0 0 0 0); } }
    .drop0 { animation: drop 0.6s steps(1) infinite; }
    .drop1 { animation: drop 0.6s steps(1) -0.3s infinite; }
    @keyframes drop { 0%, 49.9% { transform: translate(0, 0); } 50%, 100% { transform: translate(0, 1px); } }
    .peck { animation: peck 1.4s steps(1) infinite; }
    @keyframes peck { 0%, 69.9% { transform: translate(0, 0); } 70%, 84.9% { transform: translate(0, 1px); } 85%, 100% { transform: translate(0, 0); } }
    .bee { animation: buzz 2.4s steps(1) infinite; }
    ${hops('buzz', BEE_PATH)}`,
    `${tiles}${can}${daisy}${feeder}${jar}`,
  )
}

export const balconyScene: MeterScene = {
  name: 'balcony',
  label: wordsOf(t => t.scenes.balcony),
  width: WIDTH,
  height: HEIGHT,
  scale: SCALE,
  svg: balconySvg,
  small: { svg: balconySmall, centers: CENTERS },
}

files.hooks/scenes/cyberpunk.ts:
// The cyberpunk scene: the session's meters as neon things on a rooftop in
// the rain, a dark skyline behind: a power cell for the context, a neon sign
// of a bowl of noodles for the prompt cache, a stack of credit chips for the
// five-hour limit, and signal bars for the week. Each has its number
// underneath in the 3x5 pixel font.
//
// The sign's tubes go out by themselves over the cache's life, so the band
// need not be redrawn to keep it current; once the cache expires the sign is
// dark. At a quarter of the context or less the cell's charge flickers pink
// beside a loose charging cable; while the conversation is compacted the
// cable is plugged in and the cell charges.

import { wordsOf } from '../language'
import type { MeterScene, Meters } from './index'
import { countdown, COUNTDOWN_CSS, HEIGHT, hourSteps, level, percentText, pixelText, px, refill, REFILL_CSS, runsLow, SCALE, sceneSvg, SLOT, smallSceneSvg, stageOf, WIDTH } from './pixels'

// Objects stand on the rooftop at y 9.
const ROOF_Y = 9

const ROOF = '#3A3550'
const ROOF_DARK = '#2E2A40'
const SKYLINE = '#241C38'
const RAIN = '#7FA8D8'
const CYAN = '#3FF0E8'
const PINK = '#FF4FA3'
const YELLOW = '#F5E04A'
const TUBE_OFF = '#3A3A4A'
const METAL = '#5A5470'
const METAL_LIGHT = '#8A8AA0'
const WINDOW = '#141020'
const CHIP = '#F5E04A'
const CHIP_DARK = '#C9A82E'
const BAR_OFF = '#2A3A4A'

// The cell holds this many rows of charge.
const CHARGE_ROWS = 6

// Context: a power cell whose window shows its charge, the context left. At a
// quarter or less the charge flickers pink and a charging cable lies beside
// it; while the conversation is compacted the cable is plugged in, a bolt
// flashes over the cell and the charge rises.
const powerCell = (left: number | null, x: number, isCompacting: boolean) => {
  const rows = left === null ? CHARGE_ROWS : Math.max(left > 0 ? 1 : 0, Math.round((left / 100) * CHARGE_ROWS))
  const isLow = runsLow(left)
  const charge = isCompacting
    ? `<g fill="${CYAN}" style="${refill(CHARGE_ROWS - rows)}">${px(x + 6, 8 - CHARGE_ROWS, 4, CHARGE_ROWS)}</g>`
    : rows > 0 ? `<g fill="${isLow ? PINK : CYAN}"${isLow ? ' class="flicker"' : ''}>${px(x + 6, 8 - rows, 4, rows)}</g>` : ''
  const cable = isCompacting
    ? `<g fill="${METAL_LIGHT}">${px(x + 11, 4, 2, 1)}${px(x + 13, 5, 1, 4)}</g>
      <g class="bolt" fill="${YELLOW}">${px(x + 8, -2)}${px(x + 7, -1)}${px(x + 8, -1)}${px(x + 7, 0)}</g>`
    : isLow ? `<g fill="${METAL_LIGHT}">${px(x + 11, 8, 4, 1)}${px(x + 14, 7)}</g>` : ''
  return `
    <g fill="${METAL_LIGHT}">${px(x + 7, 0, 2, 1)}</g>
    <g fill="${METAL}">${px(x + 5, 1, 6, 8)}</g>
    <g fill="${WINDOW}">${px(x + 6, 2, 4, 6)}</g>
    ${charge}
    <g fill="${WINDOW}" opacity="0.6">${px(x + 6, 4, 4, 1)}${px(x + 6, 6, 4, 1)}</g>
    ${cable}
    ${percentText(left, x)}`
}

// The sign's three parts: the bowl, the chopsticks in it and the steam over it.
const bowl = (x: number) => `${px(x + 3, 4, 10, 1)}${px(x + 3, 5)}${px(x + 12, 5)}${px(x + 4, 6)}${px(x + 11, 6)}${px(x + 5, 7, 6, 1)}`
const chopsticks = (x: number) => `${px(x + 9, 3)}${px(x + 10, 2)}${px(x + 11, 1)}${px(x + 12, 0)}${px(x + 10, 3)}${px(x + 11, 2)}${px(x + 12, 1)}${px(x + 13, 0)}`
const steam = (x: number) => `${px(x + 4, 2)}${px(x + 5, 1)}${px(x + 4, 0)}${px(x + 7, 2)}${px(x + 8, 1)}${px(x + 7, 0)}`

// Cache: a neon sign of a bowl of noodles whose tubes go out by themselves
// over the cache's life: the steam first, then the chopsticks, then the bowl
// flickers; once the cache has expired the sign is dark but for a spark.
const neonSign = (left: number | null, ttl: number, x: number) => {
  const isOut = left !== null && left <= 0
  const timing = left === null || isOut ? '' : `animation-duration: ${ttl}s; animation-delay: -${ttl - left}s`
  const lit = (cls: string, fill: string, tube: string) => `<g fill="${fill}" class="${timing ? cls : ''}" style="${timing}">${tube}</g>`
  const tubes = isOut
    ? `<g class="spark" fill="${YELLOW}">${px(x + 12, 4)}</g>`
    : `${lit('until25', YELLOW, steam(x))}${lit('until50', CYAN, chopsticks(x))}${lit('until75', PINK, bowl(x))}
      ${timing ? `<g class="from75" style="${timing}"><g class="buzz" fill="${PINK}">${bowl(x)}</g></g>` : ''}`
  return `
    <g fill="${TUBE_OFF}">${steam(x)}${chopsticks(x)}${bowl(x)}</g>
    ${tubes}
    <g fill="${METAL}">${px(x + 4, 8, 8, 1)}</g>
    ${left === null ? pixelText('--', x) : isOut ? pixelText('0m', x) : countdown(left, x)}`
}

// The chips stack this high at most.
const CHIP_ROWS = 6

// Five-hour limit: a stack of credit chips on a lit pad, a chip for every
// sixth of the window still free.
const credits = (used: number | null, x: number) => {
  const left = used === null ? null : 100 - used
  const rows = left === null ? CHIP_ROWS : Math.max(left > 0 ? 1 : 0, Math.round((left / 100) * CHIP_ROWS))
  return `
    ${Array.from({ length: rows }, (_, i) => `<g fill="${i % 2 === 0 ? CHIP : CHIP_DARK}">${px(x + 5, 7 - i, 6, 1)}</g>`).join('')}
    ${rows > 0 ? `<g fill="${CHIP_DARK}">${px(x + 5, 8 - rows)}${px(x + 10, 8 - rows)}</g>` : ''}
    <g fill="${METAL}">${px(x + 3, 8, 10, 1)}</g>
    <g fill="${CYAN}">${px(x + 4, 8, 8, 1)}</g>
    ${percentText(left, x)}`
}

// Signal bars, each two pixels wide: [x, height].
const BARS: [number, number][] = [[3, 2], [6, 4], [9, 6], [12, 8]]

// Weekly limit: signal bars, one lit for every quarter of the week still
// free; the last one blinks pink.
const signal = (used: number | null, x: number) => {
  const left = used === null ? null : 100 - used
  const lit = level(left, BARS.length)
  const isLow = lit === 1
  return `
    ${BARS.map(([bx, h], i) => `<g fill="${i < lit ? (isLow ? PINK : CYAN) : BAR_OFF}"${i < lit && isLow ? ' class="flicker"' : ''}>${px(x + bx, 9 - h, 2, h)}</g>`).join('')}
    <g fill="${METAL_LIGHT}">${px(x + 13, -1, 1, 2)}</g>
    <g class="beacon" fill="${PINK}">${px(x + 13, -2)}</g>
    ${percentText(left, x)}`
}

// The skyline behind, as [x, width, top], with a lit window here and there.
const TOWERS: [number, number, number][] = [
  [0, 4, 3], [4, 5, 1], [9, 4, 4], [13, 6, 0], [19, 4, 2], [23, 5, 5], [28, 4, 1], [32, 6, 3],
  [38, 4, 0], [42, 5, 4], [47, 4, 2], [51, 6, 5], [57, 3, 1], [60, 4, 3],
]
const LIGHTS: [number, number, string][] = [[1, 4, CYAN], [6, 2, PINK], [15, 1, CYAN], [21, 3, PINK], [30, 2, CYAN], [40, 1, PINK], [49, 3, CYAN], [58, 2, PINK], [62, 4, CYAN]]

const skyline = () => `
  <g fill="${SKYLINE}">${TOWERS.map(([tx, w, top]) => px(tx, top, w, ROOF_Y - top)).join('')}</g>
  ${LIGHTS.map(([lx, ly, c], i) => `<g class="window${i % 3}" fill="${c}" opacity="0.5">${px(lx, ly)}</g>`).join('')}`

// Rain falling across the scene, as [x, period in seconds, delay].
const DROPS: [number, number, number][] = [[2, 0.9, 0], [11, 1.1, 0.4], [19, 1, 0.7], [26, 0.95, 0.2], [35, 1.05, 0.5], [43, 0.9, 0.8], [50, 1.1, 0.1], [58, 1, 0.6]]

const rain = () =>
  `<g fill="${RAIN}" opacity="0.35">${DROPS.map(([dx, period, delay]) => `<g class="drop" style="animation-duration: ${period}s; animation-delay: -${delay}s">${px(dx, -2, 1, 1)}</g>`).join('')}</g>`

const roof = () =>
  Array.from({ length: WIDTH / 4 }, (_, i) => `<g fill="${i % 2 === 0 ? ROOF : ROOF_DARK}">${px(i * 4, ROOF_Y, 4, 1)}</g>`).join('')

const cyberpunkSvg = (f: Meters) =>
  sceneSvg(
    `${COUNTDOWN_CSS}
    ${REFILL_CSS}
    .drop { animation-name: fall; animation-timing-function: steps(11); animation-iteration-count: infinite; }
    @keyframes fall { from { transform: translate(0, 0); } to { transform: translate(-1px, 11px); } }
    .window0 { animation: twinkle 3.1s steps(1) infinite; }
    .window1 { animation: twinkle 4.3s steps(1) -1.5s infinite; }
    .window2 { animation: twinkle 3.7s steps(1) -2.6s infinite; }
    @keyframes twinkle { 0%, 69.9% { opacity: 0.5; } 70%, 100% { opacity: 0; } }
    .flicker { animation: flicker 1.3s steps(1) infinite; }
    @keyframes flicker { 0%, 59.9% { opacity: 1; } 60%, 64.9% { opacity: 0.3; } 65%, 79.9% { opacity: 1; } 80%, 84.9% { opacity: 0.3; } 85%, 100% { opacity: 1; } }
    .bolt { animation: flash 0.5s steps(1) infinite; }
    @keyframes flash { 0%, 49.9% { opacity: 1; } 50%, 100% { opacity: 0; } }
    .until25, .until50, .until75, .from75 { animation-timing-function: steps(1); animation-fill-mode: forwards; }
    .until25 { animation-name: until25; }
    .until50 { animation-name: until50; }
    .until75 { animation-name: until75; }
    .from75 { animation-name: from75; }
    @keyframes until25 { 0%, 24.9% { opacity: 1; } 25%, 100% { opacity: 0; } }
    @keyframes until50 { 0%, 49.9% { opacity: 1; } 50%, 100% { opacity: 0; } }
    @keyframes until75 { 0%, 74.9% { opacity: 1; } 75%, 100% { opacity: 0; } }
    @keyframes from75 { 0%, 74.9% { opacity: 0; } 75%, 100% { opacity: 1; } }
    .buzz { animation: flicker 0.9s steps(1) infinite; }
    .spark { animation: spark 2.3s steps(1) infinite; }
    @keyframes spark { 0%, 89.9% { opacity: 0; } 90%, 94.9% { opacity: 1; } 95%, 100% { opacity: 0; } }
    .beacon { animation: flash 1.6s steps(1) infinite; }`,
    `
  ${skyline()}
  ${roof()}
  ${powerCell(f.contextLeft, 0, f.isCompacting)}
  ${neonSign(f.cacheLeft, f.cacheTtl, SLOT)}
  ${credits(f.fiveHour, SLOT * 2)}
  ${signal(f.week, SLOT * 3)}
  ${rain()}`,
  )

// The scene in the small size, on the rooftop in the rain: the power cell,
// charged as far as the context left, flickering pink beside a loose cable at
// a quarter or less, plugged in and charging while compacting; the neon bowl
// of noodles, its tubes going out over the cache's life; the stack of credit
// chips, lower as the five-hour limit goes; and the signal bars, dropping
// over the week.
const CENTERS = [4, 15, 26, 36]

const cyberpunkSmall = (f: Meters) => {
  const charge = f.isCompacting ? 4 : ([0, 1, 2, 4][stageOf(f.contextLeft)] ?? 0)
  const isLow = !f.isCompacting && runsLow(f.contextLeft)
  const cell = `
    <g fill="${METAL_LIGHT}">${px(4, 0)}</g>
    <g fill="${METAL}">${px(2, 1, 5, 6)}</g>
    <g fill="${WINDOW}">${px(3, 2, 3, 4)}</g>
    ${charge > 0 ? `<g${f.isCompacting ? ' class="fill"' : isLow ? ' class="flicker"' : ''} fill="${isLow ? PINK : CYAN}">${px(3, 6 - charge, 3, charge)}</g>` : ''}
    ${isLow ? `<g fill="${PINK}">${px(7, 6)}${px(8, 5)}</g>` : ''}
    ${f.isCompacting ? `<g fill="${CYAN}">${px(7, 3)}${px(8, 3, 1, 4)}</g>` : ''}`

  const tubes = (steam: string, sticks: string, bowl: string) => `
    <g fill="${steam}">${px(13, 1)}${px(14, 0)}${px(14, 2)}</g>
    <g fill="${sticks}">${px(16, 1, 1, 3)}${px(17, 0, 1, 3)}</g>
    <g fill="${bowl}">${px(12, 4, 7, 1)}${px(13, 5, 5, 1)}</g>`
  const sign = hourSteps(f, [tubes(CYAN, YELLOW, PINK), tubes(TUBE_OFF, YELLOW, PINK), tubes(TUBE_OFF, TUBE_OFF, PINK)], tubes(TUBE_OFF, TUBE_OFF, TUBE_OFF))

  const fiveLeft = f.fiveHour === null ? null : 100 - f.fiveHour
  const chips = [0, 1, 2, 4][stageOf(fiveLeft)] ?? 0
  const stack = `
    <g fill="${CYAN}">${px(23, 6, 7, 1)}</g>
    ${Array.from({ length: chips }, (_, i) => `<g fill="${CHIP}">${px(24, 5 - i, 5, 1)}</g><g fill="${CHIP_DARK}">${px(24, 5 - i)}${px(28, 5 - i)}</g>`).join('')}`

  const weekLeft = f.week === null ? null : 100 - f.week
  const bars = [0, 1, 2, 4][stageOf(weekLeft)] ?? 0
  const signal = [33, 35, 37, 39].map((x, i) => `<g fill="${i < bars ? (bars === 1 ? PINK : CYAN) : BAR_OFF}">${px(x, 5 - i, 1, 2 + i)}</g>`).join('')

  const skyline = `<g fill="${SKYLINE}">${px(9, 3, 2, 4)}${px(20, 2, 2, 5)}${px(31, 4, 1, 3)}</g><g fill="${YELLOW}">${px(9, 4)}${px(21, 3)}</g>`
  const rain = `<g fill="${RAIN}">${[1, 10, 19, 22, 30, 38].map((x, i) => `<g class="rain r${i % 3}">${px(x, 0)}</g>`).join('')}</g>`
  const roof = `<g fill="${ROOF}">${px(0, 7, 40, 1)}</g><g fill="${ROOF_DARK}">${Array.from({ length: 8 }, (_, i) => px(i * 5 + 4, 7)).join('')}</g>`

  return smallSceneSvg(
    `
    .fill { animation: fill 2s steps(4) both; }
    @keyframes fill { from { clip-path: inset(4px 0 0 0); } to { clip-path: inset(0 0 0 0); } }
    .flicker { animation: flicker 1.1s steps(1) infinite; }
    @keyframes flicker { 0%, 69.9% { opacity: 1; } 70%, 79.9% { opacity: 0.3; } 80%, 89.9% { opacity: 1; } 90%, 100% { opacity: 0.3; } }
    .rain { animation: rain 0.9s steps(7) infinite; }
    .r1 { animation-delay: -0.3s; }
    .r2 { animation-delay: -0.6s; }
    @keyframes rain { from { transform: translate(0, 0); } to { transform: translate(0, 7px); } }`,
    `${skyline}${rain}${roof}${cell}${sign}${stack}${signal}`,
  )
}

export const cyberpunkScene: MeterScene = {
  name: 'cyberpunk',
  label: wordsOf(t => t.scenes.cyberpunk),
  width: WIDTH,
  height: HEIGHT,
  scale: SCALE,
  svg: cyberpunkSvg,
  small: { svg: cyberpunkSmall, centers: CENTERS },
}

